import {expect,it,vi} from "vitest";
import {createSynWareTestHost} from "@syndromatic/syncloudos/sdk/testing";
import {BTFXCentralManager as BaseCentral,type BTFXPeripheral} from "@syndromatic/syncloudos/fx/bluetooth";
import {NSEData,NSEUUID} from "@syndromatic/syncloudos/foundation";
import Application,{afterAwait,afterTimer,thirdParty,BTFXCentralManager,BTFXManager,BTFXUUID,BTFXError} from "./src/SynWare/First.app/Contents/index";
import info from "./src/SynWare/First.app/Contents/Info";
const ticks=async()=>{for(let i=0;i<40;i++)await Promise.resolve();};
it("compiled app keeps attributed central construction after await, timer and callback and performs the full GATT flow",async()=>{
 const jobs:(()=>void)[]=[];vi.stubGlobal("scheduler",{postTask:(job:()=>void)=>{jobs.push(job);return Promise.resolve();}});const flush=()=>{while(jobs.length)jobs.shift()!();};const host=createSynWareTestHost({application:Application,manifest:{schemaVersion:1,...info},document});
 try{expect(()=>new BaseCentral()).toThrow(/application bundle/);expect(()=>new BTFXCentralManager()).toThrow(BTFXError);await host.render();host.adapters.permissions.allow();host.adapters.policy.allow();host.adapters.bluetooth.allow();expect("bluetooth" in host.appContext).toBe(false);
 const found:BTFXPeripheral[]=[];const state=vi.fn();const connected=vi.fn();const disconnected=vi.fn();const delegate={centralManagerDidUpdateState:state,centralManagerDidDiscoverPeripheral(_sender:BTFXCentralManager,p:BTFXPeripheral){found.push(p);},centralManagerDidConnectPeripheral:connected,centralManagerDidDisconnectPeripheral:disconnected};
 const first=await afterAwait(delegate),second=await afterTimer(delegate);let third!:BTFXCentralManager;await new Promise<void>(done=>queueMicrotask(()=>thirdParty(delegate,create=>{third=create();done();})));
 for(const central of [first,second,third]){expect(central).toBeInstanceOf(BaseCentral);expect(central).toBeInstanceOf(BTFXCentralManager);flush();expect(state).toHaveBeenCalledWith(central);central.scanForPeripherals([new BTFXUUID("180F")]);await ticks();flush();const p=found.at(-1)!;expect(p.identifier).toBeInstanceOf(NSEUUID);central.connect(p);await ticks();flush();expect(connected).toHaveBeenCalledWith(central,p);const completed=vi.fn();p.delegate={peripheralDidDiscoverServices:completed,peripheralDidDiscoverCharacteristicsForService:completed,peripheralDidDiscoverDescriptorsForCharacteristic:completed,peripheralDidUpdateValueForCharacteristic:completed,peripheralDidUpdateValueForDescriptor:completed,peripheralDidWriteValueForCharacteristic:completed,peripheralDidWriteValueForDescriptor:completed,peripheralDidUpdateNotificationStateForCharacteristic:completed};p.discoverServices(null);await ticks();flush();const s=p.services![0]!;p.discoverCharacteristics(null,s);await ticks();flush();const c=s.characteristics![0]!;p.discoverDescriptors(c);await ticks();flush();const d=c.descriptors![0]!;p.readValue(c);p.readValue(d);await ticks();flush();expect(c.value?.bytes).toEqual(new Uint8Array([42]));expect(d.value).toBe("Sensor");p.writeValue(NSEData.from(new Uint8Array([7])),c,"withResponse");p.writeValue(NSEData.from(new Uint8Array([65])),d);await ticks();flush();p.readValue(c);await ticks();flush();expect(c.value?.bytes).toEqual(new Uint8Array([7]));p.setNotifyValue(true,c);await ticks();flush();host.adapters.bluetooth.emitValue(9);flush();expect(c.value?.bytes).toEqual(new Uint8Array([9]));central.cancelPeripheralConnection(p);await ticks();flush();expect(disconnected).toHaveBeenCalledWith(central,p,null);expect(host.adapters.bluetooth.activeConnectionCount()).toBe(0);}
 expect(BTFXManager.authorization).toBe("allowedAlways");const stale=await afterAwait(delegate);stale.scanForPeripherals(null);await ticks();host.adapters.permissions.deny();host.adapters.permissions.allow();const count=found.length;flush();expect(found).toHaveLength(count);expect(()=>stale.scanForPeripherals(null)).toThrow(BTFXError);const ending=await afterAwait(delegate);await host.dispose();flush();expect(()=>ending.scanForPeripherals(null)).toThrow(BTFXError);
 }finally{await host.dispose();flush();vi.unstubAllGlobals();}
});
it.each(["read","disconnect"])("native %s denial overrides saved consent in the actual compiled entry",async boundary=>{
 const jobs:(()=>void)[]=[];vi.stubGlobal("scheduler",{postTask:(job:()=>void)=>{jobs.push(job);return Promise.resolve();}});const flush=()=>{while(jobs.length)jobs.shift()!();};const host=createSynWareTestHost({application:Application,manifest:{schemaVersion:1,...info},document});
 try{await host.render();host.adapters.permissions.allow();host.adapters.policy.allow();host.adapters.bluetooth.allow();let peripheral!:BTFXPeripheral;const completed=vi.fn();const central=await afterAwait({centralManagerDidUpdateState(){},centralManagerDidDiscoverPeripheral(_sender,p){peripheral=p;},centralManagerDidDisconnectPeripheral:completed});central.scanForPeripherals(null);await ticks();flush();central.connect(peripheral);await ticks();flush();peripheral.discoverServices(null);await ticks();flush();const service=peripheral.services![0]!;peripheral.discoverCharacteristics(null,service);await ticks();flush();peripheral.delegate={peripheralDidUpdateValueForCharacteristic:completed};host.adapters.bluetooth.deny();if(boundary==="read")peripheral.readValue(service.characteristics![0]!);else central.cancelPeripheralConnection(peripheral);await ticks();host.adapters.bluetooth.allow();flush();expect(BTFXManager.authorization).toBe("denied");expect(completed).not.toHaveBeenCalled();expect(host.adapters.bluetooth.activeConnectionCount()).toBe(0);
 }finally{await host.dispose();flush();vi.unstubAllGlobals();}
});
